package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckGlobalThis.JSDocInfo;
import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static com.google.javascript.jscomp.CheckGlobalThis.Token;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_shouldTraverse_TriageGen2Test {

    private CheckGlobalThis checker;
    private NodeTraversal t;

    @Before
    public void setUp() {
        checker = new CheckGlobalThis();
        t = mock(NodeTraversal.class);
    }

    private Node mockNode(int type) {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(type);
        return node;
    }

    @Test
    public void testNonFunctionNonAssignment() {
        Node n = mockNode(Token.NAME);
        Node parent = mockNode(Token.BLOCK);
        assertTrue(checker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testNullParent() {
        Node n = mockNode(Token.NAME);
        assertTrue(checker.shouldTraverse(t, n, null));
    }

    @Test
    public void testFunctionWithConstructorJsDoc() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(true);

        // We need to mock the private/protected method getFunctionJsDocInfo via spy or assume it's accessible/mockable
        // Since we can't override the method easily without a spy, we assume the environment allows this logic
        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(jsDoc).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithThisTypeJsDoc() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(false);
        when(jsDoc.hasThisType()).thenReturn(true);

        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(jsDoc).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithOverrideJsDoc() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(false);
        when(jsDoc.hasThisType()).thenReturn(false);
        when(jsDoc.isOverride()).thenReturn(true);

        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(jsDoc).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithNullJsDocAndValidParent() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.BLOCK);

        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(null).when(spyChecker).getFunctionJsDocInfo(n);

        assertTrue(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithInvalidParent() {
        Node n = mockNode(Token.FUNCTION);
        Node parent = mockNode(Token.EXPRESSION); // Not BLOCK, SCRIPT, NAME, or ASSIGN

        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(null).when(spyChecker).getFunctionJsDocInfo(n);

        assertFalse(spyChecker.shouldTraverse(t, n, parent));
    }

    @Test
    public void testFunctionWithValidParentTypes() {
        Node n = mockNode(Token.FUNCTION);
        int[] validParents = {Token.BLOCK, Token.SCRIPT, Token.NAME, Token.ASSIGN};

        CheckGlobalThis spyChecker = Mockito.spy(checker);
        doReturn(null).when(spyChecker).getFunctionJsDocInfo(n);

        for (int type : validParents) {
            Node parent = mockNode(type);
            assertTrue("Failed for type " + type, spyChecker.shouldTraverse(t, n, parent));
        }
    }

    @Test
    public void testAssignmentLhs() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // n is lhs
        assertTrue(checker.shouldTraverse(t, lhs, parent));
    }

    @Test
    public void testAssignmentRhsNormal() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // n is rhs
        assertTrue(checker.shouldTraverse(t, rhs, parent));
    }

    @Test
    public void testAssignmentRhsPrototypeGetProp() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.GETPROP);
        Node rhs = mockNode(Token.NAME);
        Node lastChild = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("prototype");

        assertFalse(checker.shouldTraverse(t, rhs, parent));
    }

    @Test
    public void testAssignmentRhsQualifiedNamePrototype() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getQualifiedName()).thenReturn("obj.prototype.property");

        assertFalse(checker.shouldTraverse(t, rhs, parent));
    }

    @Test
    public void testAssignmentRhsQualifiedNameNull() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getQualifiedName()).thenReturn(null);

        assertTrue(checker.shouldTraverse(t, rhs, parent));
    }
}
